const item = $input.first().json;
const SUPABASE_APIKEY = '__REDACTED_SUPABASE_ANON_KEY__';
const raw = item.authorization
  || (item.headers && (item.headers.authorization || item.headers.Authorization))
  || '';
let t = String(raw).trim();
while (/^Bearer\s+/i.test(t)) t = t.replace(/^Bearer\s+/i, '').trim();
const authorization = t ? `Bearer ${t}` : '';
return [{ json: { ...item, authorization, supabase_apikey: SUPABASE_APIKEY } }];

const item = $('Normalize auth header').first().json;
const url = 'https://uzghfpxboktnbcbbthns.supabase.co/auth/v1/user';
const maxAttempts = 3;
const waitMs = 2000;
let lastErr = null;
let data = null;
let statusCode = 0;
let attemptsUsed = 0;

if (!item.authorization) {
  return [{ json: { ok: false, status: 401, error: 'missing_token', code: 'invalid_token' } }];
}

for (let attempt = 1; attempt <= maxAttempts; attempt++) {
  attemptsUsed = attempt;
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url,
      headers: {
        Authorization: item.authorization,
        apikey: item.supabase_apikey,
      },
      returnFullResponse: true,
      json: true,
      timeout: 12000,
    });
    statusCode = res.statusCode ?? 200;
    const raw = res.body ?? res;
    data = typeof raw === 'string' ? JSON.parse(raw) : raw;
    lastErr = null;
    break;
  } catch (e) {
    lastErr = e;
    const msg = String(e.message || e);
    const retryable = /ECONNRESET|ETIMEDOUT|ENOTFOUND|ECONNREFUSED|socket hang|timeout|502|503|504|closed unexpectedly/i.test(msg);
    if (!retryable || attempt === maxAttempts) break;
    await new Promise((r) => setTimeout(r, waitMs * attempt));
  }
}

if (lastErr) {
  return [{ json: { ok: false, status: 503, error: 'auth_service_unavailable', code: 'auth_unavailable', _verify_debug: { attemptsUsed, statusCode, transport: String(lastErr.message || lastErr).slice(0, 160) } } }];
}
if (statusCode === 200 && data && data.id) {
  return [{ json: { ok: true, user_id: data.id, email: data.email || null, _verify_debug: { attemptsUsed, statusCode } } }];
}
const msg = (data && (data.msg || data.message || data.error_description)) || 'unauthorized';
return [{ json: { ok: false, status: 401, error: msg, code: 'invalid_token', _verify_debug: { attemptsUsed, statusCode } } }];
